js=r'''
var IDS=['c1','c2','c3','c4','c5'];
function le(a,b){return a<=b*(1+1e-12);}
function vrd(ok){return ok?'Выполняется':'Не выполняется';}
function calc(){
var idn=N(S('uzo')),l=P('l');
if(isNaN(l))return err('Введите суммарную длину фазных проводников (0 — если утечку сети не учитывать).');
if(l<0)return err('Длина фазных проводников не может быть отрицательной.');
var known=0,est=0,nKnown=0,nEst=0;
for(var k=0;k<IDS.length;k++){
 var raw=String($(IDS[k]).value).trim();
 if(raw==='')continue;
 var v=N(raw);
 if(isNaN(v))return err('Потребитель '+(k+1)+': введите число или оставьте поле пустым.');
 if(v<0)return err('Потребитель '+(k+1)+': значение не может быть отрицательным.');
 if(N(S(IDS[k]+'_unit'))===1){known+=v;nKnown++;}else{est+=0.4*v;nEst++;}
}
if(nKnown+nEst===0&&l===0)return err('Укажите хотя бы одного потребителя или длину фазных проводников.');
var net=0.01*l,tot=known+est+net;
if(!isFinite(tot))return err('Значения слишком велики для надёжного расчёта.');
var pue=idn/3,iec=idn*3/10,se=idn/4,half=idn/2;
var n;
if(le(half,tot))n='Суммарная утечка не меньше 0,5·IΔn = '+fmt(half,4)+' мА: исправное УЗО может отключаться уже в нормальном режиме. Разделите нагрузку на несколько групп со своими УЗО.';
else if(!le(tot,pue))n='Условие ПУЭ 7.1.83 не выполняется. Разделите нагрузку на несколько групп со своими УЗО или уточните утечки измерением. Повышать IΔn нельзя, если УЗО установлено для дополнительной защиты людей.';
else n='Условие ПУЭ 7.1.83 выполняется'+(nEst||net>0?' по оценке':'')+'. Это не гарантирует отсутствия срабатываний: фактические утечки и форма остаточного тока определяются данными оборудования и измерением.';
out(row('Утечка приборов по паспорту или замеру',fmt(known,5)+' мА ('+nKnown+' шт.)')+
row('Утечка приборов по оценке ПУЭ (0,4 мА на 1 А)',fmt(est,5)+' мА ('+nEst+' шт.)')+
row('Утечка сети (10 мкА на 1 м)',fmt(net,5)+' мА')+
row('Суммарный ток утечки',fmt(tot,5)+' мА')+
row('Доля от IΔn = '+fmt(idn,4)+' мА',fmt(100*tot/idn,4)+' %')+
row('ПУЭ 7.1.83: не более ⅓·IΔn = '+fmt(pue,4)+' мА',vrd(le(tot,pue)))+
row('IEC 60364-5-53, 531.3.2: не более 30 % IΔn = '+fmt(iec,4)+' мА',vrd(le(tot,iec)))+
row('Рекомендация Schneider Electric: не более 0,25·IΔn = '+fmt(se,4)+' мА',vrd(le(tot,se)))+
row('Статус',nEst?'Оценка: часть утечек принята по ПУЭ 7.1.83':(net>0?'Оценка: утечка сети принята по ПУЭ 7.1.83':'Расчёт по введённым значениям утечек'))+
note(n));
}
''',
about="""<div class="formula">Iут = ΣIут,i + 0,4 мА/А · ΣIнагр,j + 0,01 мА/м · L&nbsp;&nbsp;&nbsp;ПУЭ 7.1.83: Iут ≤ IΔn / 3</div>
<p>ПУЭ 7.1.83 требует, чтобы суммарный ток утечки сети с учётом присоединяемых стационарных и переносных электроприёмников в нормальном режиме не превосходил трети номинального тока УЗО. Там же дана оценка на случай отсутствия данных: ток утечки электроприёмников — 0,4 мА на 1 А тока нагрузки, ток утечки сети — 10 мкА на 1 м длины фазного проводника.</p>
<p>Калькулятор позволяет смешивать оба вида данных. Для прибора с известной утечкой (паспорт, протокол измерения) вводится её значение в миллиамперах, для остальных — ток нагрузки в амперах. Утечки складываются арифметически, как в ПУЭ. УЗО реагирует на векторную сумму токов, а модуль суммы не больше суммы модулей, поэтому арифметическое сложение не занижает результат — в том числе в трёхфазной линии, где утечки разных фаз частично компенсируются.</p>
<p><b>Три ориентира запаса.</b> Кроме условия ПУЭ показаны ещё два предела из других документов. Они близки, но не совпадают, и подменять их друг другом нельзя:</p>
<table class="t"><tr><th>Документ</th><th>Предел суммарной утечки</th><th>Для УЗО 30 мА</th></tr>
<tr><td>ПУЭ 7.1.83</td><td>⅓·IΔn</td><td>10 мА</td></tr>
<tr><td>IEC 60364-5-53, 531.3.2</td><td>30 % IΔn</td><td>9 мА</td></tr>
<tr><td>Schneider Electric, практическая рекомендация</td><td>0,25·IΔn</td><td>7,5 мА</td></tr></table>
<p>Нормативным для российских электроустановок остаётся условие ПУЭ; две другие строки показывают, насколько вывод чувствителен к выбору критерия. Запас нужен потому, что исправное УЗО может отключиться при дифференциальном токе от половины номинального: если естественная утечка подбирается к 0,5·IΔn, отключения становятся случайными.</p>""",
example="""<p>Линия с УЗО 30 мА: компьютер с паспортной утечкой 1 мА, стиральная машина без данных с током нагрузки 10 А и 30 м фазного проводника. Утечка машины по ПУЭ: 0,4 · 10 = 4 мА, утечка сети: 0,01 · 30 = 0,3 мА. Сумма — <b>5,3 мА</b>, или 17,67 % от IΔn: условие ПУЭ (не более 10 мА) выполняется, как и оба более строгих ориентира — 9 и 7,5 мА.</p>
<p>Если на ту же линию добавить обогреватель без данных с током 12 А, прибавится 0,4 · 12 = 4,8 мА, и сумма составит <b>10,1 мА</b> — больше трети от 30 мА. Такую группу делят на две со своими УЗО.</p>""",
