js=r'''
function sync(){var c=S('mode')!=='comp';hideF('ik0',c);hideF('ik0src',c);}
function init(){$('mode').addEventListener('change',sync);sync();}
function ge(a,b){return a>=b*(1-1e-12);}
function calc(){
var comp=S('mode')==='comp',u=P('u'),l=P('l'),inn=P('in');
var k=N(S('tip')),sph=N(S('sph')),spe=N(S('spe')),rho=S('mat')==='al'?0.036:0.0225;
if([u,l,inn].some(isNaN))return err('Заполните напряжение, длину линии и номинал автомата.');
if(u<=0||l<=0||inn<=0)return err('Напряжение, длина линии и номинал должны быть больше нуля.');
var ik0=NaN;
if(comp){ik0=P('ik0');
 if(isNaN(ik0))return err('Введите ток однофазного КЗ в месте установки автомата.');
 if(ik0<=0)return err('Ток КЗ в месте установки автомата должен быть больше нуля.');}
var r1=rho*(1/sph+1/spe),zc=r1*l,ia=k*inn,id,lmax,zup=0,h='';
if(!isFinite(zc)||!isFinite(ia)||zc<=0)return err('Значения слишком велики для надёжного расчёта.');
if(comp){zup=u/ik0;id=u/(zup+zc);lmax=(u/ia-zup)/r1;
 h=row('Сопротивление сети до автомата U₀/I′',fmt(zup,4)+' Ом');}
else{id=0.8*u/zc;lmax=0.8*u/(ia*r1);}
if(!isFinite(id)||!isFinite(lmax)||!isFinite(zup))return err('Значения слишком велики для надёжного расчёта.');
var ok=ge(id,ia),meas=comp&&S('ik0src')==='measured';
h+=row('Сопротивление петли линии Zц (фаза + PE)',fmt(zc,4)+' Ом')+
row(comp?'Ток КЗ в конце линии (метод композиции)':'Ток КЗ в конце линии (0,8·U₀/Zц)',fmt(id,4)+' А');
if(comp)h+=row('Напряжение в месте установки автомата при этом КЗ','≈ '+fmt(100*zc/(zup+zc),3)+' % U₀');
h+=row('Порог гарантированного мгновенного расцепления Ia',fmt(ia,4)+' А ('+k+'·In)')+
row('Запас Iкз / Ia',fmt(id/ia,3))+
row('Предельная длина линии по этому условию',lmax>0?fmt(lmax,4)+' м':'нет: ток КЗ на вводе не выше Ia')+
row('Статус',meas?'Недостаточно данных':(ok?'Условие мгновенного расцепления выполняется':'Условие мгновенного расцепления не выполняется'));
var n=meas?'Ток I′ измерен без поправки на худшие условия: замер отражает напряжение сети и нагрев проводников в момент измерения, и минимальный ток КЗ может оказаться меньше. Числа показаны справочно; вывод о гарантированном мгновенном расцеплении по ним не делается. Для вывода нужен минимальный ток КЗ из проекта или от сетевой организации. ':(ok?'Ток КЗ в конце линии не ниже порога гарантированного мгновенного расцепления. ':'Ток КЗ в конце линии ниже порога гарантированного мгновенного расцепления: сократите линию, увеличьте сечение или пересмотрите аппарат. ');
if(comp&&zc/(zup+zc)<0.8)n+='Напряжение на вводе при таком КЗ ниже 80 %: для этой линии допущение конвенционального метода было бы оптимистичным. ';
if(k===20)n+='Граница 20·In для D должна подтверждаться паспортом аппарата: МЭК 60898 допускает для D и 50·In. ';
if(k===50)n+='Верхняя граница D не подтверждена паспортом, поэтому взято 50·In, которое допускает МЭК 60898. ';
n+='Проверено одно условие метода; время отключения, термическая стойкость проводников и отключающая способность автомата не проверяются. Сопротивление контактов и соединений увеличивает петлю — при сомнениях её измеряют.';
out(h+note(n));
}
''',
about="""<div class="formula">Zц = ρ · L · (1/Sф + 1/SPE)<br>Конвенциональный метод: Iкз = 0,8 · U₀ / Zц&nbsp;&nbsp;&nbsp;Lmax = 0,8 · U₀ · Sф / (ρ · (1 + m) · Ia),&nbsp;m = Sф / SPE<br>Метод композиции: Iкз = U₀ · I′ / (U₀ + Zц · I′)</div>
<p>ρ — удельное сопротивление жил при рабочей температуре: 0,0225 Ом·мм²/м для меди и 0,036 Ом·мм²/м для алюминия — значения Schneider Electric для конвенционального метода. L — длина линии в одну сторону, Sф и SPE — сечения фазного и защитного проводников, Ia — ток гарантированного мгновенного расцепления, то есть верхняя граница характеристики: 5, 10 или 20·In. Для D граница 20·In должна подтверждаться паспортом аппарата: МЭК 60898 допускает для D и 50·In, и без подтверждения калькулятор берёт 50·In.</p>
<p><b>Почему к Zц не прибавляется источник.</b> Конвенциональный метод предполагает, что при КЗ напряжение в месте установки автомата остаётся не ниже 80 % номинального фазного, и по Schneider Electric этот коэффициент учитывает все падения напряжения выше рассматриваемой точки. Поэтому в формулу входит только петля самой линии. Если включить в Zц ещё и питающую сеть, как при проверке по полному Z в калькуляторе минимального тока КЗ, оценка получится строже.</p>
<p><b>Когда известен ток КЗ на вводе линии.</b> Метод композиции Schneider Electric находит ток в конце петли по известному току КЗ в её начале: сопротивление вышестоящей сети U₀/I′ и сопротивление линии складываются арифметически. Модуль суммы сопротивлений не больше суммы модулей, поэтому такое сложение не завышает ток КЗ. Множитель 0,8 здесь не применяется: вышестоящая сеть уже учтена через I′. Оба метода дают одинаковую предельную длину при I′ = 5·Ia; при более слабой сети метод композиции строже конвенционального, при более сильной — мягче.</p>
<p><b>Измеренный I′.</b> Замер показывает ток при напряжении сети и нагреве проводников в момент измерения, а минимальный ток КЗ может быть меньше. Поэтому по измеренному без поправки I′ калькулятор показывает числа справочно и вывода о срабатывании не делает — так же, как калькулятор минимального тока КЗ поступает с измеренным Z.</p>
<p><b>Реактивное сопротивление.</b> Когда проводники цепи проложены рядом, реактивное сопротивление мало по сравнению с активным, и для сечений до 120 мм² им пренебрегают. Поэтому калькулятор ограничен сечениями до 120 мм².</p>
<table class="t"><tr><th>Медь, Sф = SPE</th><th>B16 (Ia = 80 А)</th><th>C16 (Ia = 160 А)</th></tr>
<tr><td>1,5 мм²</td><td>73,33 м</td><td>36,67 м</td></tr>
<tr><td>2,5 мм²</td><td>122,2 м</td><td>61,11 м</td></tr>
<tr><td>4 мм²</td><td>195,6 м</td><td>97,78 м</td></tr></table>
<p>В таблице — предельная длина по конвенциональному методу при U₀ = 220 В. Для промышленного автомата с уставкой Im, для предохранителя или для сечения вне списка предельную длину тем же методом считает <a href="dlina-kabelya-po-toku-kz.html">калькулятор максимальной длины линии</a>.</p>""",
example="""<p>Медная линия 2,5 мм² с PE того же сечения, длина 30 м, U₀ = 220 В, автомат C16 (Ia = 160 А). Zц = 0,0225 · 30 · (1/2,5 + 1/2,5) = 0,54 Ом. Конвенциональный метод: Iкз = 0,8 · 220 / 0,54 ≈ <b>325,9 А</b> — выше 160 А. Предельная длина: 0,8 · 220 · 2,5 / (0,0225 · 2 · 160) ≈ <b>61,11 м</b>.</p>
<p>Если по проекту минимальный ток КЗ фаза–PE на вводе линии равен 1 кА, метод композиции даёт 220 · 1000 / (220 + 0,54 · 1000) ≈ <b>289,5 А</b> — меньше, чем по конвенциональному методу: напряжение на вводе при таком КЗ около 71 %, и для этой короткой линии допущение «не ниже 80 %» оптимистично. Для длинных линий картина обратная: предельная длина по методу композиции ≈ 64,17 м против 61,11 м. Одинаковыми эти длины становятся при I′ = 5·Ia = 800 А.</p>""",
