 dict(id="rho", label="Удельное сопротивление грунта ρ", unit="Ом·м", val="50", hint="Лучше — по измерению или изысканиям; можно вписать своё значение"),
 dict(type="select", id="zad", label="Как задать длину контура", opts=[("ab","Размеры прямоугольного контура a × b"),("l","Длина замкнутого проводника L")], val="ab"),
