js=r'''
var DMAX=[[15,0],[20,5],[25,9],[30,12],[40,17],[50,20],[60,23],[80,28],[100,31],[120,34],[150,38]];
function dmax(L){for(var i=0;i<DMAX.length;i++){if(L<=DMAX[i][0]*(1+1e-12))return DMAX[i][1];}return null;}
function sync(){var ab=S('zad')==='ab';hideF('a',!ab);hideF('b',!ab);hideF('l',ab);}
function init(){$('grunt').addEventListener('change',function(){$('rho').value=S('grunt');});$('zad').addEventListener('change',sync);sync();}
function calc(){
var rho=P('rho'),rt=P('rt'),L,ab=S('zad')==='ab',far=false;
if(isNaN(rho)||isNaN(rt))return err('Заполните удельное сопротивление грунта и цель проекта.');
if(rho<=0||rt<=0)return err('Удельное сопротивление и цель должны быть больше нуля.');
if(ab){var a=P('a'),b=P('b');
 if(isNaN(a)||isNaN(b))return err('Введите обе стороны контура.');
 if(a<=0||b<=0)return err('Стороны контура должны быть больше нуля.');
 L=2*(a+b);far=Math.max(a,b)>3*Math.min(a,b)*(1+1e-12);}
else{L=P('l');
 if(isNaN(L))return err('Введите длину замкнутого проводника.');
 if(L<=0)return err('Длина проводника должна быть больше нуля.');}
var r=2*rho/L,need=2*rho/rt;
if(!isFinite(r)||!isFinite(need)||!isFinite(L))return err('Значения слишком велики для надёжного расчёта.');
var d=far?null:dmax(L),cmp,dt,n;
if(far)dt='не оценивалось: стороны контура длиннее 3:1';
else if(d===null)dt='не оценивалось: контур длиннее 150 м';
else if(d===0)dt='нет: для контура до 15 м формула скорее завышает R';
else dt='до '+d+' %';
if(!ab&&d!==null)dt+=' — при сторонах не длиннее 3:1';
if(r>rt*(1+1e-12))cmp='оценка выше заданной цели';
else if(d===null)cmp='оценка не выше цели, но погрешность формулы для такого контура не оценивалась';
else if(r*(1+d/100)>rt*(1+1e-12))cmp='оценка не выше цели, но запас меньше возможного занижения — цель не подтверждена';
else if(!ab)cmp='оценка не выше цели, но форма контура не задана — чтобы учесть занижение формулы, задайте стороны';
else cmp='не выше заданной цели и с учётом возможного занижения формулы';
if(far)n='Для контура со сторонами длиннее 3:1 занижение формулы больше, чем в проверочной таблице, и калькулятор его не оценивает. ';
else if(d===0)n='Для такого короткого контура формула скорее завышает сопротивление, то есть оценка с запасом. ';
else if(d===null)n='Для контура длиннее 150 м занижение формулы может превышать 38 %, и калькулятор эту погрешность не оценивает. ';
else n='Для контура такой длины формула может занижать сопротивление: по численной проверке для однородного грунта — до '+d+' %. Длина контура для цели по формуле поэтому тоже может оказаться недостаточной. ';
if(!ab)n+='Поправка рассчитана для контура со сторонами не длиннее 3:1; в режиме длины форма контура не задана, поэтому цель с учётом занижения не подтверждается. ';
out(row('Длина замкнутого контура L',fmt(L,4)+' м')+
row('Оценочное сопротивление R ≈ 2ρ/L',fmt(r,4)+' Ом')+
row('Возможное занижение формулы (однородный грунт)',dt)+
row('Сравнение с целью',fmt(r,4)+' Ом — '+cmp)+
row('Длина контура для цели '+fmt(rt,4)+' Ом по формуле',fmt(need,4)+' м')+
row('Статус','Оценка, требуется измерение')+
note(n+'Слоистость грунта, промерзание и высыхание в эту поправку не входят, поэтому готовый заземлитель измеряют.'));
}
''',
about="""<div class="formula">R ≈ 2ρ / L&nbsp;&nbsp;&nbsp;L = 2 · (a + b) — для прямоугольного контура</div>
<p>ρ — удельное сопротивление грунта, Ом·м; L — длина замкнутого проводника, м. Это приближение Schneider Electric для горизонтального заземлителя в виде кольца, уложенного по периметру котлована под фундамент. В поисковой выдаче формула источника свёрстана изображением и множитель 2 дословно не виден, поэтому его точность проверена независимо — численным расчётом (таблица ниже). Для существующих зданий тот же проводник укладывают вокруг наружных стен на глубину не менее 1 м.</p>
<p><b>Условия укладки, на которых основана оценка.</b> Голый проводник должен быть в непосредственном контакте с грунтом, а не лежать в щебёночной или гравийной подготовке под бетон; при укладке в котлован — в грунте не менее чем на 50 см ниже этой подготовки. Ни заземлитель, ни вертикальные выпуски от него не должны касаться бетона фундамента.</p>
<p><b>Кольцо и стержни.</b> Для вертикальных стержней тот же источник даёт R ≈ ρ/(n·L), где L — длина стержня (см. <a href="raschet-zazemleniya.html">расчёт заземления стержнями</a>). В формуле кольца L — длина всего контура, а коэффициент вдвое больше. Прямую, незамкнутую полосу в траншее считает <a href="gorizontalnyy-zazemlitel.html">калькулятор горизонтального заземлителя</a>, одиночный стержень с учётом диаметра и заглубления — <a href="vertikalnyy-zazemlitel.html">калькулятор вертикального заземлителя</a>.</p>
<table class="t"><tr><th>Длина контура L</th><th>ρ = 50 Ом·м</th><th>ρ = 100 Ом·м</th><th>ρ = 500 Ом·м</th></tr>
<tr><td>20 м</td><td>5 Ом</td><td>10 Ом</td><td>50 Ом</td></tr>
<tr><td>40 м</td><td>2,5 Ом</td><td>5 Ом</td><td>25 Ом</td></tr>
<tr><td>60 м</td><td>1,67 Ом</td><td>3,33 Ом</td><td>16,67 Ом</td></tr></table>
<p><b>В какую сторону ошибается формула.</b> Она не учитывает глубину укладки и толщину проводника, а сопротивление кольца растёт с его размером медленнее, чем 1/L. При проверке калькулятора 2ρ/L сравнили с численным расчётом прямоугольного контура в однородном грунте (метод моментов с зеркальным изображением; на круговом кольце он совпадает с классической формулой Дуайта в пределах 0,1 %). Проводник — от медного троса 25 мм² до полосы 40×4 мм, глубина 0,5–1 м, соотношение сторон от 1:1 до 3:1:</p>
<table class="t"><tr><th>Длина контура L</th><th>Строгий расчёт относительно 2ρ/L</th></tr>
<tr><td>20 м</td><td>от −15 до +5 %</td></tr>
<tr><td>30 м</td><td>от −8 до +12 %</td></tr>
<tr><td>40 м</td><td>от −3 до +17 %</td></tr>
<tr><td>60 м</td><td>от +4 до +23 %</td></tr>
<tr><td>100 м</td><td>от +12 до +31 %</td></tr>
<tr><td>150 м</td><td>от +19 до +38 %</td></tr></table>
<p>У маленького контура формула скорее завышает сопротивление, а у типичного дома с периметром от 40 м — <b>занижает</b>, и тем сильнее, чем длиннее контур. Поэтому калькулятор сравнивает с целью не только саму оценку, но и оценку, увеличенную на верхнюю границу этого занижения для ближайшей большей длины из таблицы расчёта. К прямоугольнику со сторонами длиннее 3:1 поправка не применяется: у вытянутого контура 30 × 1 м строгий расчёт даёт на 25–44 % больше формулы. В режиме «длина проводника» форма контура не задана, поэтому цель с учётом занижения калькулятор не подтверждает — для этого задайте стороны контура. Слоистость грунта, промерзание и высыхание сюда не входят: ρ берут по изысканиям или измерению, а готовый заземлитель проверяют прибором.</p>""",
example="""<p>Дом 12 × 8 м, контур по периметру: L = 2 · (12 + 8) = 40 м. При ρ = 100 Ом·м оценка R ≈ 2 · 100 / 40 = <b>5 Ом</b>; численный расчёт для того же контура даёт 4,9–5,7 Ом в зависимости от проводника и глубины. Чтобы получить 4 Ом в том же грунте, по формуле понадобился бы контур длиной 2 · 100 / 4 = <b>50 м</b>, а по численному расчёту — 51–60 м. В сухом грунте с ρ = 500 Ом·м тот же дом даст около <b>25 Ом</b>.</p>""",
